        self.sensors = []
        self.central_control = None
        self.device_registry = {}

    def add_device(self, id, type):
        self.device_registry[id] = {
            'type': type,
            'config': {}
        }

    def register_sensor(self, location, telemetry_rate=10):
        sensor_id = f"{location}_sensor_{datetime.now().timestamp()}"
        self.sensors.append(sensor_id)
        self.device_registry[sensor_id]['type'] = 'sensor'
        device_config = {
            'location': location,
            'telemetry_rate': telemetry_rate,
            'data_history': []
        }
        self.device_registry[sensor_id]['config'] = device_config

    def send_command(self, device_id, action, parameters=None):
        device_config = self.device_registry[device_id]['config']
        if action == 'turn_on':
            device_config['status'] = 'online'
        elif action == 'adjust_setting':
            device_config['target'] = parameters
        self.central_control.broadcast([action], [device_id])
